public enum PaymentMethod { CreditCard, DebitCard, UPI, NetBanking, Wallet }
public enum PaymentStatus { Pending, Authorized, Captured, Failed, Refunded }

public class Payment
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid OrderId { get; set; }
    public decimal Amount { get; set; }
    public PaymentMethod Method { get; set; }
    public PaymentStatus Status { get; private set; } = PaymentStatus.Pending;
    public string? TransactionId { get; private set; }
    public DateTime CreatedAt { get; } = DateTime.UtcNow;

    public void Authorize(string transactionId)
    {
        Status = PaymentStatus.Authorized;
        TransactionId = transactionId;
    }

    public void Capture()
    {
        if (Status != PaymentStatus.Authorized) throw new InvalidOperationException();
        Status = PaymentStatus.Captured;
    }

    public void Fail(string reason)
    {
        Status = PaymentStatus.Failed;
        TransactionId = reason;
    }
}
